#!/usr/bin/python3
# SPDX-License-Identifier: GPL-3.0-or-later
"""Build a fully offline, searchable resource page; no third-party scripts."""
import csv,html,json
from pathlib import Path
ROOT=Path(__file__).resolve().parent.parent
with (ROOT/'data/glossary.csv').open(encoding='utf-8',newline='') as f:rows=list(csv.DictReader(f))
items=''.join('<tr><td>'+html.escape(r['english'])+'</td><td>'+html.escape(r['tetun'])+'</td><td>'+html.escape(r['category'])+'</td></tr>' for r in rows)
page='''<!doctype html><html lang="tet-TL"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tetun • Edukasaun OS</title>
<style>:root{font-family:system-ui,sans-serif;color:#163c35;background:#f2f5ef;line-height:1.55}*{box-sizing:border-box}body{margin:0}main{max-width:1050px;margin:auto;padding:36px 24px}header{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap;border-bottom:1px solid #c8d5cd;padding-bottom:25px}h1{font-size:clamp(30px,5vw,48px);margin:8px 0;line-height:1.12}h2{font-size:24px;margin:0 0 14px}.tag{font-size:13px;letter-spacing:.12em;text-transform:uppercase}.badge{background:#fff1cb;padding:8px 16px;border-radius:40px;align-self:start;color:#674b09}.grid{display:grid;grid-template-columns:1fr 1fr;gap:24px;margin:26px 0}.card{background:white;border:1px solid #d5ded6;border-radius:14px;padding:22px}pre{background:#123e36;color:#edf6eb;white-space:pre-wrap;overflow-wrap:anywhere;padding:18px;border-radius:10px;font-size:13px}code{font-family:ui-monospace,monospace}.note{font-size:14px;color:#516d62}input{width:100%;padding:14px;border:1px solid #8aa897;border-radius:8px;font-size:16px;background:#fff;margin-bottom:15px}table{width:100%;border-collapse:collapse;background:#fff;text-align:left}th,td{padding:12px;border-bottom:1px solid #dee6df}th{position:sticky;top:0;background:#16584c;color:white}td:last-child{font-size:13px;color:#56766a}button{font:inherit;padding:8px 12px;border:1px solid #afc4b5;background:#fff;border-radius:7px;cursor:pointer;margin:3px}button:focus,input:focus{outline:3px solid #bd8f25;outline-offset:2px}a{color:#155b52}.table-wrap{overflow-x:auto}footer{margin-top:30px;font-size:13px;color:#516d62}@media(max-width:700px){.grid{grid-template-columns:1fr}main{padding:22px 16px}th,td{padding:9px}}[hidden]{display:none!important}</style>
<main><header><div><div class="tag">Edukasaun OS · Language resources · 0.2.0</div><h1>Pakote Lian Tetun</h1><p>Glosáriu no matadalan ba <code>tet_TL.UTF-8</code></p></div><div class="badge">Esbosu · Hein revizaun INL</div></header>
<div class="grid"><section class="card"><h2>Instalasaun / Installation</h2><pre>sudo apt install ./eduka-language-pack-tet_0.2.0_all.deb
eduka-tet demo
eduka-tet enable --user</pre><p>Sai husi sesaun no tama fali. / Log out and sign in again.</p><p class="note">Run enable as your normal user, without sudo. Activation detects the desktop; Plasma and GNOME/GDM have specific backends. Sign out and sign in again. Some Wayland sessions require login-manager configuration. See INSTALL-ID.md.</p><p>Atu dezativa / To undo:</p><pre>eduka-tet disable --user</pre></section>
<section class="card"><h2>Standar no revizaun</h2><p><code>tet</code> · ISO 639-2<br><code>tet-TL</code> · BCP 47 tag<br><code>tet_TL.UTF-8</code> · glibc locale</p><p class="note">INL-oriented original translations. This community package has not been endorsed by INL, ISO or Debian. It supplies 13 partial native application catalogs and its own catalogs; full desktop coverage remains pending. Qt/LXQt may require explicit catalog loading.</p><p><a href="glossary.csv">Download glossary CSV</a> · <a href="metadata.json">Package metadata</a> · <a href="native-manifest.json">Native coverage</a> · <a href="source-manifest.json">Book references / rights</a></p></section></div>
<section class="card"><h2>Karáter Tetun</h2><p class="note">Klik atu kopia / Click to copy. Keyboard alternatives: US international dead keys, Portuguese layout or a Compose key.</p><div id="characters"></div><p id="copied" role="status"></p></section>
<section style="margin-top:28px"><h2>Glosáriu · COUNT termu</h2><label for="query">Buka termu / Search English or Tetun</label><input id="query" type="search" placeholder="Save, seña, atualiza..." autocomplete="off"><p class="note" id="count" role="status">COUNT termu. Termu hotu presiza revizaun INL.</p><div class="table-wrap"><table><thead><tr><th scope="col">English</th><th scope="col">Tetun · draft</th><th scope="col">Category</th></tr></thead><tbody>ITEMS</tbody></table></div><p id="none" hidden>La hetan rezultadu. / No results found.</p></section>
<footer>GPL-3.0-or-later · Original community terminology. No dictionary or audio corpus is redistributed. Native catalogs retain their GNU GPL/LGPL licenses; LXQt files retain LGPL-2.1-or-later. Fully offline; no tracking or remote assets.</footer></main>
<script>const rows=[...document.querySelectorAll('tbody tr')];const q=document.querySelector('#query');q.addEventListener('input',()=>{let n=0;const term=q.value.normalize('NFC').toLowerCase();for(const r of rows){r.hidden=!r.textContent.normalize('NFC').toLowerCase().includes(term);if(!r.hidden)n++}document.querySelector('#count').textContent=n+' / '+rows.length+' termu · presiza revizaun INL';document.querySelector('#none').hidden=n!==0});for(const c of ['á','é','í','ó','ú','ñ','Á','É','Í','Ó','Ú','Ñ',"'"]){const b=document.createElement('button');b.textContent=c;b.setAttribute('aria-label','Kopia '+c);b.onclick=async()=>{try{await navigator.clipboard.writeText(c);document.querySelector('#copied').textContent='Kopia: '+c}catch(e){document.querySelector('#copied').textContent='Hili no kopia karáter: '+c}};document.querySelector('#characters').append(b)}</script></html>'''
page=page.replace('COUNT',str(len(rows))).replace('ITEMS',items)
(ROOT/'data/resources.html').write_text(page,encoding='utf-8')
print('Offline glossary generated.')
